"protocol" | 
/**  The server refused a command (IMAP NO/BAD). */
"server_rejected" | 
/**  Writing is turned off for this account. */
"read_only" | 
/**  The server lacks something the app requires (IMAP4rev1). */
"unsupported_server" | 
/**  The system keychain refused to store, read or delete the password. */
"keychain" | 
/**  An account with this email address is already set up. */
"account_exists" | 
/**
 *  The account has no folder for this action: archive (`archive`), trash (`delete`), junk
 *  (`spam`) or inbox (`notSpam`). The UI asks which folder to use (`setMailboxRole`) or
 *  offers to create one (`createMailbox`).
 */
"missing_mailbox" | 
/**
 *  The messages lie in the trash, where deleting removes them for good. The UI asks and
 *  then sends the action `deletePermanently`.
 */
"confirmation_required" | 
/**
 *  The action cannot be undone (a permanent delete, a created folder, a move still on its
 *  way or not yet visible in its target folder). Nothing was changed.
 */
"not_undoable" | 
/**  A tag contains spaces or characters IMAP does not allow in keywords. */
"invalid_keyword";

/**
 *  Local row id of an identity (`identity.id`). Not stable across devices (the settings sync
 *  uses the identity's UUID). Exported since stage 7 (identities in the settings).
 */
export type IdentityId = number;

/**  A sender identity of an account over IPC. */
export type IdentityInfo = {
	id: IdentityId,
	accountId: AccountId,
	email: string,
	name: string,
	replyTo: string | null,
	isDefault: boolean,
};

/**  Fields of a new or changed identity. */
export type IdentityInput = {
	email: string,
	name: string,
	replyTo: string | null,
};

/**  The error as it crosses the IPC bridge: `{ code, message, detail }`. */
export type IpcError = {
	code: ErrorCode,
	/**  English fallback text; the UI shows an i18n text chosen by `code`. */
	message: string,
	/**  Technical detail, never secrets. */
	detail: string | null,
};

export type LanguagePreference = "system" | "en" | "de";

/**  Answer of `describeLink`: what the user confirms before the system browser opens. */
export type LinkInfo = {
	/**  The real target, complete, for display. */
	target: string,
	/**  Lower-case scheme (`https`, `http`, `mailto`, ...). */
	scheme: string,
	/**  Host in Unicode form; null for `mailto` and hostless URLs. */
	host: string | null,
	/**  Visible link text, white space collapsed, at most 200 characters; empty for images. */
	text: string,
	warnings: LinkWarning[],
	/**  Only `http`, `https` and `mailto` can be opened. */
	openable: boolean,
};

/**  Why a link deserves a second look. */
export type LinkWarning = 
/**  The link text names another domain than the target. */
{ kind: "domainMismatch"; shownDomain: string; targetDomain: string } | 
/**
 *  The host mixes scripts or uses look-alike characters (IDN homograph); `ascii_host` is
 *  its punycode form.
 */
{ kind: "confusableHost"; asciiHost: string } | 
/**  The host is a bare IP address. */
{ kind: "ipAddressHost" } | 
/**  The URL carries a user name or password (`https://bank.example@evil.example/`). */
{ kind: "credentialsInUrl" } | 
/**  A scheme other than http, https and mailto; the link cannot be opened. */
{ kind: "unsupportedScheme" };

/**
 *  Keyset cursor of a message list: pass `nextCursor` of one page back to get the next page.
 *  Opaque to the UI; today it is the [`MessageId`] of the last item of the page.
 */
export type ListCursor = number;

/**  What the user asks for. One action on many messages is one batch ([`BatchId`]). */
export type MailAction = { type: "markRead" } | { type: "markUnread" } | { type: "flag" } | { type: "unflag" } | { type: "addKeyword"; keyword: string } | { type: "removeKeyword"; keyword: string } | 
/**
 *  Moves to the mailbox with the role `archive`. Without one the action fails with
 *  [`ActionError::MissingMailbox`], so the UI can ask which mailbox to use (then
 *  `setMailboxRole`) or whether to create one (an operation of its own).
 */
{ type: "archive" } | 
/**
 *  Moves to the trash. Messages that already lie in the trash are only deleted with
 *  [`MailAction::DeletePermanently`]; `Delete` on them fails with
 *  [`ActionError::ConfirmationRequired`].
 */
{ type: "delete" } | 
/**
 *  Deletes for good (EXPUNGE). The UI asks before sending it; this action is the explicit
 *  confirmation the core requires.
 */
{ type: "deletePermanently" } | 
/**  Moves to another mailbox of the same account. */
{ type: "move"; target: MailboxId } | 
/**  Moves to the mailbox with the role `junk`. */
{ type: "spam" } | 
/**  Moves messages from the junk mailbox to the inbox; others are left alone. */
{ type: "notSpam" };

/**  A mailbox as the UI sees it (sidebar, folder tree). */
export type Mailbox = {
	id: MailboxId,
	accountId: AccountId,
	/**  Full decoded path, for example `Projekte/2026`. The inbox is `INBOX`. */
	path: string,
	/**  Last segment of `path`, for the tree. The UI shows a translated name for roles. */
	name: string,
	/**  Hierarchy delimiter, null if the server has a flat namespace. */
	delimiter: string | null,
	parentId: MailboxId | null,
	role: MailboxRole,
	roleSource: RoleSource,
	/**  `false` for placeholders that cannot hold messages (`\Noselect`, `\NonExistent`). */
	selectable: boolean,
	/**  Unread messages stored locally. */
	unread: number,
	/**  Messages stored locally (grows during the first sync). */
	total: number,
};

/**  Local row id of a mailbox (`mailbox.id`). Not stable across devices. */
export type MailboxId = number;

/**  What a mailbox is for. At most one mailbox per account has each role except `custom`. */
export type MailboxRole = "inbox" | "sent" | "drafts" | "archive" | "trash" | "junk" | 
/**  Virtual folder with every message (Gmail "All Mail", `\All`). */
"all" | 
/**  Virtual folder with flagged messages (Gmail "Starred", `\Flagged`). */
"flagged" | 
/**  An ordinary folder. */
"custom";

/**
 *  When the reading pane marks an opened message as read (stage 4). The UI does the marking
 *  (an ordinary `markRead` action), and only for accounts with `writesEnabled`; read-only
 *  accounts mark nothing.
 */
export type MarkReadOnOpen = 
/**  As soon as the message is shown. */
"immediately" | 
/**  After it was shown for [`MARK_READ_DELAY_MS`] without the selection changing. */
"afterDelay" | "never";

/**
 *  Outbox state of a message as its list row shows it (stage 4). If several operations touch
 *  the message, the one that needs the user wins: `failed`, then `conflict`, then `pending`.
 */
export type MessageActivity = 
/**  A change waits for the server (`queued` or `in_flight`); the row already shows it. */
"pending" | 
/**  A change failed and was reverted locally. The activity view offers retry and discard. */
"failed" | 
/**
 *  The message was changed elsewhere meanwhile and the server's state was kept. The
 *  activity view explains it.
 */
"conflict";

/**  The body as the UI shows it. */
export type MessageBody = 
/**
 *  Sanitized HTML for `<iframe sandbox="allow-same-origin" srcdoc=...>`. Starts with the
 *  mandatory meta CSP; every `href` is a placeholder of `render_token`; external images are
 *  replaced unless remote content was loaded.
 */
{ kind: "html"; srcdoc: string; renderToken: RenderToken; 
/**  External images and styles that were blocked (0 when `remote_loaded`). */
blockedRemote: number; remoteLoaded: boolean } | 
/**
 *  Plain text for the app's own theme. Links are separate segments, opened through the same
 *  check as HTML links (`describeLink` with this `render_token`).
 */
{ kind: "text"; segments: TextSegment[]; renderToken: RenderToken } | 
/**
 *  Not stored locally; a fetch is running. `messageBodyAvailable` or `messageBodyFailed`
 *  follows; then ask again.
 */
{ kind: "loading" } | 
/**  Not stored locally and cannot be fetched now. */
{ kind: "unavailable"; reason: BodyUnavailableReason; 
/**  Details for `fetchFailed`, null otherwise. */
error: IpcError | null };

/**
 *  Local id of a message (`message.id`): its sort date in Unix seconds, or the next free number
 *  above it (decision 0003). Larger is newer. Below 2^33, so exact as a JavaScript number.
 */
export type MessageId = number;

/**  One row of the message list. */
export type MessageListItem = {
	id: MessageId,
	accountId: AccountId,
	mailboxId: MailboxId,
	/**  First `From` address, null if none. */
	from: Address | null,
	/**  `To` addresses, for lists of sent mail and drafts. */
	to: Address[],
	/**  Empty if the message has no subject. */
	subject: string,
	/**  Sort date in Unix milliseconds. */
	date: number,
	unread: boolean,
	flagged: boolean,
	answered: boolean,
	draft: boolean,
	hasAttachments: boolean,
	/**  Keywords as stored (for example `$Forwarded`), see [`Flags::keywords`]. */
	keywords: string[],
	/**
	 *  Start of the text, white space collapsed, at most 256 characters; null until the body
	 *  was parsed (opened or prefetched).
	 */
	preview: string | null,
	/**
	 *  Outbox state of a change to this message, for a small symbol in the row. Absent when
	 *  nothing is pending or needs the user (most rows), so pages stay small.
	 */
	activity?: MessageActivity | null,
};

/**  One page of a message list, newest first. */
export type MessagePage = {
	items: MessageListItem[],
	/**  Pass to the next call to continue; null on the last page. */
	nextCursor: ListCursor | null,
};

/**  Defects of a message that the reading pane mentions. */
export type MessageProblem = 
/**  The MIME structure is damaged (missing boundary, truncated); shown as far as readable. */
"brokenStructure" | 
/**  A text part declared an unknown charset; decoded with replacement characters. */
"unknownCharset" | 
/**  A part's transfer encoding is broken; it is shown raw or left out. */
"undecodablePart" | 
/**  No readable text part (only attachments, or empty). */
"noContent" | 
/**  The message could not be parsed at all and is shown as raw text. */
"rawFallback";

/**  A message in one mailbox, as the list shows it (`MessageListItem::mailbox_id` and `id`). */
export type MessageRef = {
	mailboxId: MailboxId,
	messageId: MessageId,
};

/**  What `getMessage` returns: everything the reading pane shows. */
export type MessageView = {
	id: MessageId,
	/**  For the account color. */
	accountId: AccountId,
	header: MessageViewHeader,
	body: MessageBody,
	/**
	 *  Formats the message can be shown in (`html`, `text`, or both). Switching is another
	 *  `getMessage` with that format; it is served locally.
	 */
	formats: BodyFormat[],
	/**  Real attachments (not the inline images the HTML shows), in message order. */
	attachments: AttachmentInfo[],
	/**
	 *  A large message of which only the text parts are stored; attachments are fetched when
	 *  saved or opened.
	 */
	partial: boolean,
	/**  Defects found while parsing; the UI shows a hint. Empty for well-formed mail. */
	problems: MessageProblem[],
};

/**  Header of the reading pane. Addresses decoded (RFC 2047), groups flattened. */
export type MessageViewHeader = {
	from: Address[],
	to: Address[],
	cc: Address[],
	/**  Only known for mail the user sent (Sent, Drafts). */
	bcc: Address[],
	replyTo: Address[],
	/**  Sort date in Unix milliseconds, as in the list. */
	date: number,
	/**  Empty if the message has no subject. */
	subject: string,
};

/**  Result of `openAttachment`. */
export type OpenAttachmentResult = 
/**  Handed to the system's default app. */
{ kind: "opened" } | 
/**
 *  Executable and not confirmed: show the warning, then call again with
 *  `confirmedExecutable: true`. Nothing was written or opened.
 */
{ kind: "needsConfirmation" };

/**  Id of one operation (`operation.id`). Never reused; also the order of execution. */
export type OperationId = number;

/**  One operation as the activity view shows it. */
export type OperationInfo = {
	id: OperationId,
	batch: BatchId,
	accountId: AccountId,
	action: ActionKind,
	kind: OperationKind,
	state: OperationState,
	/**
	 *  Source mailbox and message; null for `create_mailbox`, or when they were deleted
	 *  locally since.
	 */
	mailboxId: MailboxId | null,
	messageId: MessageId | null,
	/**  Target of a move. */
	targetMailboxId: MailboxId | null,
	/**  Times the command was sent. */
	attempts: number,
	/**  Why it failed (`failed`), or the last transient error. */
	error: IpcError | null,
	conflict: ConflictReason | null,
	notice: OperationNotice | null,
	/**  Unix milliseconds. */
	createdAt: number,
	updatedAt: number,
};

/**  What an operation does on the server. */
export type OperationKind = "set_flag" | "move" | "expunge" | "create_mailbox";

/**  Something the user should know about a confirmed operation. */
export type OperationNotice = 
/**
 *  The server has no UIDPLUS and other messages in the source mailbox were marked deleted,
 *  so a plain EXPUNGE would have removed them too. The message was copied but its original
 *  stays in the source, marked deleted, until the mailbox is expunged.
 */
"left_marked_deleted";

/**
 *  Where an operation stands.
 * 
 *  `queued` → `in_flight` (the command is about to be sent) → `confirmed` | `failed` |
 *  `conflict`. After a crash or a lost connection, `in_flight` operations are checked against
 *  the server before anything is repeated.
 */
export type OperationState = 
/**  Recorded, local change applied, waiting for the server. */
"queued" | 
/**  Sent or about to be sent; the outcome is not known yet. */
"in_flight" | 
/**  The server did it. */
"confirmed" | 
/**
 *  The server refused or the outbox gave up; the local change was reverted. The user can
 *  retry or discard it.
 */
"failed" | 
/**
 *  The server state changed meanwhile (the message was moved, deleted or modified
 *  elsewhere); the server wins and the user is told ([`ConflictReason`]).
 */
"conflict";

/**
 *  How many operations of an account wait for the server or need the user (status badge,
 *  activity view). Confirmed ones are not counted.
 */
export type OutboxCounts = {
	accountId: AccountId,
	/**  `queued` or `in_flight`. */
	pending: number,
	/**  `failed`: refused or given up, local change reverted. Retry or discard. */
	failed: number,
	/**  `conflict`: changed elsewhere meanwhile, the server's state was kept. Discard. */
	conflict: number,
};

/**  Operating system the app runs on. */
export type Platform = "macos" | "windows" | "linux";

/**  User preferences stored in the `setting` table. */
export type Preferences = {
	theme: ThemePreference,
	language: LanguagePreference,
};

/**  How far back bodies are prefetched (Inbox, Sent, Drafts and flagged mail). */
export type PrefetchPeriod = "days7" | "days30" | "days90" | "days365" | "all";

/**  Prefetch settings (device class: disk space and connection differ per device; not synced). */
export type PrefetchSettings = {
	period: PrefetchPeriod,
	/**
	 *  Messages up to this RFC822.SIZE (bytes) are prefetched whole; larger ones only with
	 *  their text parts, so they can still be read offline. 0 prefetches text only.
	 */
	maxMessageSize: number,
};

export type PrefetchState = 
/**  Everything in the period is stored. */
"idle" | "running" | 
/**  The account is offline; continues when it reconnects. */
"paused";

/**  Progress of the prefetch of one account (event `prefetchProgress`). */
export type PrefetchStatus = {
	state: PrefetchState,
	/**  Bodies stored in the current run, and the run's total. */
	done: number,
	total: number,
	/**  Bytes fetched in the current run (below 2^53). */
	bytes: number,
};

/**
 *  Provider-specific advice for the setup form. The UI shows one note per hint; the server
 *  settings are filled in either way.
 */
export type ProviderHint = 
/**  Needs an app password (Google account with 2-step verification). */
"gmail" | 
/**  Needs an app-specific password (Apple ID). */
"icloud" | 
/**  Needs an app password (Yahoo account security settings). */
"yahoo" | 
/**  Needs an app password (Fastmail settings, Privacy & Security). */
"fastmail" | 
/**
 *  Outlook.com, Hotmail, Live: Microsoft only accepts OAuth sign-in, which the app supports
 *  from stage 14. A password login is expected to fail.
 */
"outlook" | 
/**
 *  Proton Mail works only through Proton Mail Bridge on this computer (paid plan): use the
 *  user name and password that Bridge shows, and trust Bridge's certificate in the system.
 */
"proton" | 
/**  GMX: IMAP access must be turned on first (web mail settings, POP3/IMAP). */
"gmx" | 
/**  WEB.DE: IMAP access must be turned on first (web mail settings, POP3/IMAP). */
"webde" | 
/**
 *  Telekom (t-online.de, magenta.de): needs the separate email password from the Telekom
 *  customer center, not the Telekom login password.
 */
"tonline";

/**
 *  Reading preferences stored in the `setting` table (stage 4). Separate from [`Preferences`],
 *  so the appearance settings keep their shape.
 */
export type ReadingPreferences = {
	markReadOnOpen: MarkReadOnOpen,
};

/**  Scope of `loadRemoteContent`. */
export type RemoteContentScope = 
/**  This rendering only; nothing is stored. */
"once" | 
/**  Always for this sender address in this account (stored, synced in stage 11). */
"sender";

/**
 *  Opaque id of one rendering of a body: 32 lowercase hex digits (128 random bits), made by the
 *  core. Link placeholders of that rendering carry it (`https://link.invalid/<token>/<index>`);
 *  the real targets stay in the core under it. Unguessable, so a mail cannot point at the links
 *  of another rendering.
 */
export type RenderToken = string;

/**  Why a mailbox has its role. */
export type RoleSource = 
/**  The server said so: a SPECIAL-USE attribute (RFC 6154), or the name `INBOX`. */
"server" | 
/**  Guessed from the folder name (English and German names, Gmail folders). */
"heuristic" | 
/**  Set by the user; survives every refresh of the folder list. */
"user" | 
/**  No role (`custom`) and no reason to think otherwise. */
"none";

/**  Result of `saveAttachment`. */
export type SaveAttachmentResult = 
/**  Written to the path the user chose in the system dialog. */
{ kind: "saved"; path: string } | 
/**  The user closed the dialog. */
{ kind: "cancelled" };

/**
 *  Where the query's words occur in the fields the list shows. Computed from the stored text
 *  (the index holds no text, decision 0003); a match deep in the body has no range here.
 */
export type SearchHighlights = {
	subject: TextRange[],
	/**  In the sender's display name, or in the address when there is no name. */
	from: TextRange[],
	preview: TextRange[],
};

/**
 *  One result: the message as a list row (one of its locations), every mailbox it lies in, and
 *  the highlighted ranges.
 */
export type SearchHit = {
	message: MessageListItem,
	/**  All locations, ascending; `message.mailboxId` is one of them. */
	mailboxIds: MailboxId[],
	highlights: SearchHighlights,
	/**
	 *  The whole message is stored locally, so its text was searched. Otherwise only headers
	 *  (and the text parts of a large message) were: "search on the server" can find more.
	 */
	bodyLocal: boolean,
};

/**  State of the full-text index. */
export type SearchIndexState = 
/**  Every stored message is indexed. */
"ready" | 
/**
 *  Existing messages are being indexed (after the update to stage 7); results may be
 *  missing older messages until it is done.
 */
"building" | 
/**  A new index is being built in the background; searches use the old one meanwhile. */
"rebuilding";

export type SearchIndexStatus = {
	state: SearchIndexState,
	/**  0..=100, by message dates (the index is built from old to new). */
	percent: number,
};

/**  One page of results, newest first. */
export type SearchPage = {
	hits: SearchHit[],
	/**  Null on the last page. A page can be shorter than the limit and still have a next one. */
	nextCursor: ListCursor | null,
	/**  Parser errors, contradictions and unknown accounts or mailboxes, sorted by position. */
	problems: SearchProblem[],
	/**  Every term of the query, for chips. */
	terms: SearchTermInfo[],
	/**
	 *  The query cannot match anything (a contradiction, an unknown account or mailbox, an
	 *  empty date range); `hits` is empty.
	 */
	matchesNothing: boolean,
	index: SearchIndexStatus,
};

/**  A problem at a place in the query; the UI marks the range and shows a text for the code. */
export type SearchProblem = {
	code: SearchProblemCode,
	range: TextRange,
};

/**  What a problem in the query is. The parser's error kinds plus what only the engine knows. */
export type SearchProblemCode = "unclosed_quote" | "missing_value" | "unknown_filter" | "unknown_value" | "invalid_date" | "invalid_age" | "nothing_to_search" | "prefix_too_short" | "missing_term" | "misplaced_or" | "or_needs_text" | "or_with_exclusion" | "too_long" | "too_many_terms" | 
/**  The term contradicts another one (`is:unread is:read`); the query finds nothing. */
"conflict" | 
/**  `account:` names no account (address, name or id). */
"unknown_account" | 
/**  `in:` names no mailbox of the accounts searched. */
"unknown_mailbox" | 
/**
 *  The server cannot search for this term (`has:attachment`, `is:snoozed`); it is applied
 *  to the local data of the results only (server search).
 */
"not_on_server";

/**  One search call. */
export type SearchRequest = {
	/**  As typed, at most 2048 bytes are read. */
	query: string,
	scope: SearchScope,
	/**  `nextCursor` of the previous page; null for the first page. */
	cursor: ListCursor | null,
	/**  1..=200. */
	limit: number,
	/**
	 *  Search as you type: the word the input ends in matches as a prefix (`rech` finds
	 *  "Rechnung"). Off for a submitted search.
	 */
	typing: boolean,
	/**
	 *  The user's region writes `01/02/2026` month first (United States). Dates with dots,
	 *  ISO dates and month names do not depend on it.
	 */
	monthFirst?: boolean,
};

/**
 *  Where a search looks. Hidden accounts are left out of `all` and `group` (as from the
 *  unified inbox); searching one account or mailbox explicitly always works.
 */
export type SearchScope = 
/**  Every visible account. */
{ kind: "all" } | { kind: "account"; accountId: AccountId } | { kind: "mailbox"; mailboxId: MailboxId } | 
/**  The visible accounts of a group. */
{ kind: "group"; groupId: AccountGroupId };

/**
 *  One term as typed, for a chip: kind, whether it was excluded with `-`, the whole term and
 *  its value (without key and quotes).
 */
export type SearchTermInfo = {
	kind: SearchTermKind,
	negated: boolean,
	range: TextRange,
	valueRange: TextRange,
	/**  Part of an `OR` group (`a OR b`). */
	alternative: boolean,
};

/**  What a term of the query is, for chips. */
export type SearchTermKind = "text" | "from" | "to" | "cc" | "subject" | "filename" | "in" | "account" | "has_attachment" | "is_unread" | "is_read" | "is_flagged" | "is_snoozed" | "before" | "after" | "older_than" | "newer_than";

/**
 *  Transport security of a server connection. There is deliberately no plaintext option: a
 *  password never travels unencrypted, and the test server offers TLS and STARTTLS as well.
 */
export type Security = 
/**  TLS from the first byte (IMAP 993, SMTP 465). */
"tls" | 
/**
 *  Plain connect, then `STARTTLS` before anything else (IMAP 143, SMTP 587). If the server
 *  does not offer STARTTLS, the connection fails; it never continues unencrypted.
 */
"starttls";

/**
 *  Result of searching on the server (IMAP SEARCH over the read-only connection) for messages
 *  whose content is not stored locally.
 */
export type ServerSearchResult = {
	/**
	 *  Messages the server found whose whole body is not stored locally, newest first, at most
	 *  the request's limit. Every hit is a stored message (headers are always local).
	 */
	hits: SearchHit[],
	/**  More hits than returned. */
	truncated: boolean,
	/**  Mailboxes searched. */
	searched: MailboxId[],
	/**  Mailboxes whose search failed (offline, refused); the rest still counts. */
	failed: MailboxId[],
	/**  Server hits not stored locally yet (first sync still running). */
	notSynced: number,
	/**  Problems of the query, including terms the server cannot search (`notOnServer`). */
	problems: SearchProblem[],
};

/**  Where and how to reach one server (IMAP or SMTP). No password: that lives in the keychain. */
export type ServerSettings = {
	host: string,
	port: number,
	security: Security,
	username: string,
};

/**  Progress of the first sync of one mailbox. */
export type SyncProgress = {
	mailboxId: MailboxId,
	/**  Messages of this mailbox stored locally so far. */
	done: number,
	/**  Messages in this mailbox on the server (EXISTS when the pass started). */
	total: number,
};

/**  A range of UTF-16 code units (`start..end`). */
export type TextRange = {
	start: number,
	end: number,
};

/**  A piece of a text body. */
export type TextSegment = { kind: "text"; text: string } | 
/**  A URL or address found in the text; `index` for `describeLink`/`openLink`. */
{ kind: "link"; text: string; index: number };

export type ThemePreference = "system" | "light" | "dark";

/**  One message of an open thread. */
export type ThreadEntry = {
	/**  As a list row of one of its locations (the requested mailbox if it lies there). */
	message: MessageListItem,
	/**  All locations, ascending. */
	mailboxIds: MailboxId[],
};

/**
 *  One conversation in a list: the newest of its messages in the listed mailbox, how many it
 *  has (in all mailboxes of the account) and how many of those are unread.
 */
export type ThreadListItem = {
	/**  The newest message of the thread in this mailbox; the row shows it. */
	message: MessageListItem,
	/**
	 *  Local thread id; null while the message is not threaded yet (right after the update to
	 *  stage 7). Changes when threads merge: open a thread by `message.id` (`getThread`).
	 */
	threadId: number | null,
	messageCount: number,
	/**  Messages of the thread unread in at least one mailbox. */
	unreadCount: number,
	/**
	 *  Sort date of the thread's newest message anywhere (Unix milliseconds), for example a
	 *  reply in Sent.
	 */
	lastActivity: number,
};

export type ThreadPage = {
	items: ThreadListItem[],
	/**  Null on the last page. */
	nextCursor: ListCursor | null,
};

/**  Every message of a thread over all mailboxes of its account, oldest first. */
export type ThreadView = {
	threadId: number | null,
	messages: ThreadEntry[],
	/**
	 *  Messages in the thread; more than `messages.length` if the thread was cut to the newest
	 *  [`MAX_THREAD_MESSAGES`].
	 */
	total: number,
};

/**  Which inboxes a unified view mixes. */
export type UnifiedView = 
/**  The inboxes of every visible account. */
{ kind: "all" } | 
/**  The inboxes of the group's visible accounts. */
{ kind: "group"; groupId: AccountGroupId };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}
